export function findById(id) { return ARTICLES.find(x => x.id === id); }
export function search(q) {
  const s = String(q||'').toLowerCase();
  if (!s) return ARTICLES.slice();
  return ARTICLES.filter(x => JSON.stringify(x).toLowerCase().includes(s));
}
export function bySpecialty(spec) {
  return ARTICLES.filter(x => (x.specialty||x.category||'').toLowerCase() === String(spec||'').toLowerCase());
}
export function enabledOnly() { return ARTICLES.filter(x => x.enabled !== false); }
export const COUNT = ARTICLES.length;
